/* 代码应该是来自[叶峻峣](https://www.zhihu.com/people/thoughts-memo) */
/* 样式页  */
.card {
	BACKGROUND-COLOR: #201256;
	COLOR           : #FFFFFF;
	FONT-FAMILY     : 楷体;
	FONT-SIZE       : 18pt;
	LINE-HEIGHT     : 1.7em;
	/TEXT-INDENT     : 2em;
	PADDING         : 1em 5% 0 5%;
}

.src {
    color: grey;
    font-style: italic;
    font-size: 16px;
    text-align: center;
}

.cloze {
	BACKGROUND-COLOR: #ffffff;
	COLOR           : #fffe75;
	FONT-WEIGHT     : bold;
	LETTER-SPACING  : 5px;
}

.clozed {
	BACKGROUND-COLOR: #FFD499;
	FONT-WEIGHT     : bold;
}

.nightMode .cloze {
	BACKGROUND-COLOR: #F7ED4E;
}

.Reference {
	/BACKGROUND-COLOR: #C29CC0;
	/COLOR           : #FFF2E2;
	LINE-HEIGHT     : 2.5em;
	FONT-SIZE       : 12pt;
	font-style: italic;
}

h1 {
	FONT-SIZE: 24pt;
}

h2 {
	FONT-SIZE: 22pt;
}

h3 {
	FONT-SIZE: 20pt;
}

